// Demo: Kafka 消费者 — 使用 mask-go-common-lib/mq，带优雅退出
package demo

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/company/mask-go-common-lib/logging"
	"github.com/company/mask-go-common-lib/mq"
)

type OrderPaidHandler struct {
	log *logging.Logger
	// 注入下游 usecase，消费者层不做业务
	uc OrderUsecase
}

type OrderUsecase interface {
	MarkOrderPaid(ctx context.Context, orderID string) error
}

// Handle 是消费回调；返回 error 表示处理失败，mq 层决定是否重试 / 进死信队列。
func (h *OrderPaidHandler) Handle(ctx context.Context, msg *mq.Message) error {
	var evt OrderPaidEvent
	if err := json.Unmarshal(msg.Value, &evt); err != nil {
		// 协议错误一般不可恢复，落告警队列即可，不要无限重试
		h.log.ErrorContext(ctx, "invalid order paid payload",
			"topic", msg.Topic, "err", err)
		return nil // 不重试
	}

	if err := h.uc.MarkOrderPaid(ctx, evt.OrderID); err != nil {
		return fmt.Errorf("mark order paid %s: %w", evt.OrderID, err)
	}
	return nil
}

// StartConsumer 在 cmd/main.go 或 server 初始化时调用。
func StartConsumer(ctx context.Context, cfg *mq.Config, h *OrderPaidHandler) error {
	c, err := mq.NewConsumer(cfg, &mq.ConsumerOptions{
		Topic:   cfg.Topics["order_pay_status_updated"], // 来自 config 的命名映射
		GroupID: cfg.Env + "_order_pay_status_consumer",
		Handler: h.Handle,
	})
	if err != nil {
		return err
	}
	// Start 会阻塞直到 ctx 取消（优雅退出）
	return c.Start(ctx)
}

// Demo: Kafka 生产者 — 使用 mask-go-common-lib/mq 与 naming 命名规范
// 禁止直接用 sarama / kafka-go 裸客户端（会绕开命名规范与可观测性）
package demo

import (
	"context"
	"encoding/json"

	"github.com/company/mask-go-common-lib/mq"
	"github.com/company/mask-go-common-lib/naming"
)

// OrderPaidEvent 是业务事件载荷。字段 snake_case，便于跨语言消费。
type OrderPaidEvent struct {
	OrderID   string `json:"order_id"`
	UserID    string `json:"user_id"`
	AmountRaw string `json:"amount_raw"` // 金额走字符串，避免 JSON 精度丢失
	PaidAt    int64  `json:"paid_at"`    // Unix 毫秒
}

// OrderProducer 用构造注入，禁止全局单例。
type OrderProducer struct {
	p     mq.Producer
	topic string
}

func NewOrderProducer(cfg *mq.Config) (*OrderProducer, func(), error) {
	p, cleanup, err := mq.NewProducer(cfg)
	if err != nil {
		return nil, nil, err
	}
	// 命名规范：{env}_{service}_{entity}_{action}
	topic := naming.TopicInProject(cfg.Env, "order", "pay_status", "updated")
	return &OrderProducer{p: p, topic: topic}, cleanup, nil
}

// PublishPaid 发送订单已支付事件。ctx 必须来自上游（携带 trace/span）。
func (op *OrderProducer) PublishPaid(ctx context.Context, evt *OrderPaidEvent) error {
	payload, err := json.Marshal(evt)
	if err != nil {
		return err // 上层 wrap 用 fmt.Errorf("marshal order paid: %w", err)
	}
	// mq.Producer 内部会把 ctx 里的 trace header 注入到 Kafka message headers
	return op.p.Send(ctx, op.topic, evt.OrderID /* partition key */, payload)
}

// 跨项目 topic 示例：
