// Demo: 最小 Kratos 服务骨架 — cmd/main.go
// 使用 mask-go-common-lib 统一初始化 logging / tracing / alarm / config
package main

import (
	"context"
	"os"
	"os/signal"
	"syscall"

	"github.com/go-kratos/kratos/v2"
	"github.com/go-kratos/kratos/v2/log"

	"github.com/company/mask-go-common-lib/alarm"
	"github.com/company/mask-go-common-lib/config"
	"github.com/company/mask-go-common-lib/logging"
	"github.com/company/mask-go-common-lib/tracing"
)

// Name 是服务在服务发现 / 日志 / 追踪中的唯一标识。
// 命名约定：kebab-case，语义清晰，避免 util/common。
const Name = "order-service"

func main() {
	// 1. 配置（ConfigMap 友好 + 热加载）
	cfg, err := config.NewFromFile("configs/dev/" + Name + ".yaml")
	if err != nil {
		panic(err) // init 阶段 panic 允许；业务代码禁用
	}

	// 2. 结构化日志（自动提取 trace_id / span_id）
	logger := logging.New(Name, cfg.Env)
	log.SetLogger(logger) // Kratos 全局适配

	// 3. OTel tracing（dev 全量 / prod 10% 采样）
	shutdown, err := tracing.Init(context.Background(), Name, cfg.Env)
	if err != nil {
		panic(err)
	}
	defer shutdown(context.Background())

	// 4. 告警管理（异步去重 + 多渠道）
	alarmMgr := alarm.NewManager(cfg.Alarm)
	defer alarmMgr.Close()

	// 5. Wire 装配的 App（服务 / 中间件 / 路由在 wire_gen.go 中自动拼装）
	app, cleanup, err := wireApp(cfg, logger, alarmMgr)
	if err != nil {
		panic(err)
	}
	defer cleanup()

	// 6. 优雅退出
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	if err := app.Run(); err != nil {
		log.Errorw("msg", "app run failed", "err", err)
		os.Exit(1)
	}
	<-ctx.Done()
}

// buildApp 是 Kratos 应用工厂，wire.go 里会把它声明为 Provider。
func buildApp(logger log.Logger, hs *httpServer, gs *grpcServer) *kratos.App {
	return kratos.New(
		kratos.Name(Name),
		kratos.Logger(logger),
		kratos.Server(hs, gs),
	)
}

// httpServer / grpcServer 的具体初始化在 internal/server/ 下，
// 使用 middleware 包挂载 recovery / tracing / metrics / validate 中间件。
type httpServer = kratos.Server
type grpcServer = kratos.Server

// Demo: GORM Repo 模式 — 游标分页、软删、context 超时、禁止 SELECT *
package data

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/shopspring/decimal"
	"gorm.io/gorm"

	"github.com/company/mask-go-common-lib/logging"
)

// Order 对应 trade.orders 表；字段顺序与表一致便于审查
type Order struct {
	ID             int64           `gorm:"primaryKey"`
	UserID         int64           `gorm:"column:user_id"`
	Amount         decimal.Decimal `gorm:"type:decimal(28,8)"`
	FilledQuantity decimal.Decimal `gorm:"type:decimal(28,8)"`
	Status         int16
	Side           int16
	IdempotencyKey string `gorm:"column:idempotency_key"`
	CreatedAt      time.Time
	UpdatedAt      time.Time
	DeletedAt      gorm.DeletedAt `gorm:"index"` // 软删
}

func (Order) TableName() string { return "trade.orders" }

// OrderRepo 定义契约（接口放使用方，实现放 data 包）
// 使用方（biz 层）依赖这个接口而非 *OrderRepoImpl
type OrderRepo interface {
	Create(ctx context.Context, o *Order) (*Order, error)
	GetByID(ctx context.Context, id int64) (*Order, error)
	ListByUserCursor(ctx context.Context, userID, afterID int64, limit int) ([]*Order, error)
}

type orderRepo struct {
	db  *gorm.DB
	log *logging.Logger
}

func NewOrderRepo(db *gorm.DB, log *logging.Logger) OrderRepo {
	return &orderRepo{db: db, log: log}
}

// Create 写入订单；幂等键冲突时返回已有记录而非错误（契约）。
func (r *orderRepo) Create(ctx context.Context, o *Order) (*Order, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second) // DB 查询必须带超时
	defer cancel()

	err := r.db.WithContext(ctx).Create(o).Error
	if err != nil {
		// 实际生产会区分唯一冲突 → 走幂等分支
		return nil, fmt.Errorf("create order (idem=%s): %w", o.IdempotencyKey, err)
	}
	return o, nil
}

// GetByID 软删记录自动排除。
func (r *orderRepo) GetByID(ctx context.Context, id int64) (*Order, error) {
	ctx, cancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer cancel()

	var o Order
	err := r.db.WithContext(ctx).
		Select("id, user_id, amount, filled_quantity, status, side, idempotency_key, created_at, updated_at").
		Where("id = ?", id).
		First(&o).Error
	if errors.Is(err, gorm.ErrRecordNotFound) {
		return nil, ErrOrderNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("get order %d: %w", id, err)
	}
	return &o, nil
}

// ListByUserCursor 使用游标分页，禁止大 OFFSET。
// afterID = 0 表示第一页；调用方拿到最后一条的 ID 传回作下一页的 afterID。
func (r *orderRepo) ListByUserCursor(ctx context.Context, userID, afterID int64, limit int) ([]*Order, error) {
	if limit <= 0 || limit > 200 {
		limit = 50
	}
	ctx, cancel := context.WithTimeout(ctx, 1*time.Second)
	defer cancel()

	var out []*Order
	err := r.db.WithContext(ctx).
		Select("id, user_id, amount, status, created_at").
		Where("user_id = ? AND id > ?", userID, afterID).
		Order("id ASC").
		Limit(limit).
		Find(&out).Error
	if err != nil {
		return nil, fmt.Errorf("list orders user=%d after=%d: %w", userID, afterID, err)
	}
	return out, nil
}

// ErrOrderNotFound 应放在 biz 或 errno 包（业务错误走 xerror.New(errno.OrderNotFound)）
var ErrOrderNotFound = errors.New("order not found")

-- Demo: PostgreSQL Migration — 遵循团队 database.md 规范
-- 文件命名：migrations/000003_create_orders_table.up.sql
-- 配套：migrations/000003_create_orders_table.down.sql（回滚脚本必须成对）
-- 工具：goose 或 golang-migrate 均可

