BEGIN;

-- Schema 按业务模块划分，禁止在 public 建业务表
CREATE SCHEMA IF NOT EXISTS trade;

-- 核心业务表：无前缀；表名复数名词
CREATE TABLE trade.orders (
    -- 主键：业务 ID 直接对外暴露（避免 UUID 的索引代价，除非有强需求）
