    metadata        JSONB,

    -- 必备字段（审计 + 软删）
    created_at      TIMESTAMPTZ(6) NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ(6) NOT NULL DEFAULT NOW(),
    deleted_at      TIMESTAMPTZ(6),                 -- 软删标记，允许 NULL
    created_by      VARCHAR(64),
    updated_by      VARCHAR(64)
