// NewDB 构造 PostgreSQL 连接（生产应从 config 读取 DSN 并设连接池上限）。
func NewDB(cfg *Config, logger *logging.Logger) (*gorm.DB, func(), error) {
	db, err := gorm.Open( /* postgres.Open(cfg.DSN) */ nil)
	if err != nil {
		return nil, nil, err
	}
	cleanup := func() {
		sqlDB, _ := db.DB()
		_ = sqlDB.Close()
	}
	return db, cleanup, nil
}

